import{_ as a,o as e,c as r,a5 as o}from"./chunks/framework.CxQKysS2.js";const u=JSON.parse('{"title":"给学习留一个出口：从这篇手记开始","description":"","frontmatter":{"slug":"start-writing","status":"published","tags":["学习方法","复盘"],"projects":[],"title":"给学习留一个出口：从这篇手记开始","date":"2026-11-01","category":"reflections","excerpt":"不必等到完全掌握才开始分享。把问题、尝试和理解写下来，就是学习发生的证据。","readingTime":"3 分钟"},"headers":[],"relativePath":"mailbox/reflections/start-writing.md","filePath":"content/articles/reflections/start-writing.md","lastUpdated":null}'),i={name:"mailbox/reflections/start-writing.md"};function s(l,t,n,c,p,d){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="给学习留一个出口-从这篇手记开始" tabindex="-1">给学习留一个出口：从这篇手记开始 <a class="header-anchor" href="#给学习留一个出口-从这篇手记开始" aria-label="Permalink to &quot;给学习留一个出口：从这篇手记开始&quot;">​</a></h1><p class="post-meta">2026.11.01 · 学习与生活 · 示例文章</p><p>有时候，一天写了很多代码，关掉编辑器后却很难说清自己究竟学到了什么。这个博客，想成为这些零散经验的落脚点。</p><div class="tip custom-block"><p class="custom-block-title">关于示例</p><p>这是用于展示排版的模板文章，不代表已经完成的项目成果。正式发布前，可以替换成自己的真实记录。</p></div><h2 id="从一个具体问题开始" tabindex="-1">从一个具体问题开始 <a class="header-anchor" href="#从一个具体问题开始" aria-label="Permalink to &quot;从一个具体问题开始&quot;">​</a></h2><p>与其写“今天学习了 Spring”，不如记录一个可复现的问题：接口为什么返回 404？控制器是否扫描到了？请求路径和请求方式是否匹配？</p><p>把宽泛的主题缩小，文章就有了清晰的起点。</p><h2 id="用自己的话重新解释" tabindex="-1">用自己的话重新解释 <a class="header-anchor" href="#用自己的话重新解释" aria-label="Permalink to &quot;用自己的话重新解释&quot;">​</a></h2><p>可以给每篇笔记保留三个部分：</p><ol><li><strong>遇到了什么</strong>：记录环境、操作和完整现象。</li><li><strong>如何确认原因</strong>：区分猜测与实际证据。</li><li><strong>下次怎么处理</strong>：留下可复用的步骤。</li></ol><h2 id="给不确定的地方留位置" tabindex="-1">给不确定的地方留位置 <a class="header-anchor" href="#给不确定的地方留位置" aria-label="Permalink to &quot;给不确定的地方留位置&quot;">​</a></h2><p>暂时没有答案也没关系。标记“待验证”，比把猜测写成结论更有价值。</p><blockquote><p>笔记不必是终点，它也可以是下一次探索的起点。</p></blockquote><p>下一篇，试着从今天遇到的一个小问题开始。</p>',14)])])}const _=a(i,[["render",s]]);export{u as __pageData,_ as default};
